    const fullPathCandidate = path.join(baseDirPath, filename);

    // Resolve the full path candidate to its absolute, normalized form.
    const resolvedFullPath = path.resolve(fullPathCandidate);

    // Crucial Path Traversal Check:
    // Ensure that the resolved full path is still within the resolved base directory.
    // This is done by checking if the resolved full path starts with the resolved base directory path.
    // We append path.sep to baseDirPath for the startsWith check to ensure that
