 * @param {string} email - The email to check.
 * @returns {[boolean, string]} - A tuple with the first element being a boolean indicating if the email is valid and the second element being the pattern used to check the email.
 */
const checkEmail = (email) => {
  // Regular expression for email validation.
  // This pattern aims to cover common valid email formats while avoiding common invalid ones,
  // striking a balance between RFC strictness and practical usage.
  //
  // Breakdown of the pattern:
  // ^                                      - Asserts the start of the string.
  //
  // Local Part (before @):
  // [a-zA-Z0-9]+                           - Requires the local part to start with one or more
  //                                          alphanumeric characters.
  // (?:[._%+-][a-zA-Z0-9]+)*               - Optionally allows subsequent segments separated by
  //                                          a special character (dot '.', underscore '_', percent '%',
  //                                          plus '+', or hyphen '-'). Each special character must be
  //                                          followed by one or more alphanumeric characters.
  //                                          This prevents the local part from starting or ending with
  //                                          a special character, and from having consecutive special characters
  //                                          (e.g., "user..name" or "user.@").
  //
  // @                                      - Matches the literal "@" symbol, separating local and domain parts.
  //
  // Domain Part (after @):
  // (?:                                    - Non-capturing group for one or more domain labels.
  //   [a-zA-Z0-9]                          - A domain label must start with an alphanumeric character.
  //   (?:[a-zA-Z0-9-]*[a-zA-Z0-9])?        - Optionally followed by zero or more alphanumeric or hyphen characters,
  //                                          but must end with an alphanumeric character.
  //                                          This prevents domain labels from starting or ending with a hyphen.
  //   \.                                   - Each label (except the last TLD) must be followed by a literal dot.
  // )+                                     - Requires one or more such domain labels (e.g., "def.ghi.com.").
  //
  // Top-Level Domain (TLD):
  // [a-zA-Z]{2,}                           - The TLD must consist of at least two alphabetic characters.
  //
  // $                                      - Asserts the end of the string.
  //
  // This pattern successfully validates the example: abc.123@def.ghi.com.uk
  // - "abc.123" matches the local part pattern.
  // - "def.ghi.com.uk" matches the domain part pattern.
  //
  // It helps avoid common false positives for invalid email formats such as:
  // - user..name@domain.com (consecutive dots in local part)
