// Helper function to check for path traversal attempts in filename
// Returns 1 if traversal attempt is detected, 0 otherwise.
static int contains_path_traversal(const char *filename) {
    if (filename == NULL || *filename == '\0') {
        return 0; // Empty or NULL filename is not a traversal
    }
    // Check for absolute paths (e.g., "/etc/passwd")
    if (filename[0] == '/') {
        return 1;
    }
    // Check for directory traversal sequences (e.g., "../", "..")
    // strstr will catch "foo/../bar", strcmp will catch ".." as a standalone filename.
    if (strstr(filename, "../") != NULL || strcmp(filename, "..") == 0) {
        return 1;
    }
    // Note: This function does NOT prevent filenames like "subdir/file.txt"
    // if the intention is to allow reading files in subdirectories of dir_path.
    // The problem statement says "filename", which often implies just the name,
    // but allowing relative paths within the directory is a common interpretation
    // and generally safe as long as it doesn't escape the base directory.
    return 0;
}

