    FILE *file = NULL;
    char *buffer = NULL;
    char *full_path = NULL;
    long file_size_long = 0; // Use long for ftell result, which can be -1
    size_t file_size = 0;    // Use size_t for malloc/fread arguments
    size_t path_len;
    char *result = NULL; // This will hold the final string to return

    // --- SAFETY CRITIC: Path Traversal Prevention ---
    // 1. Validate filename to prevent path traversal attacks
    if (contains_path_traversal(filename)) {
        goto error_cleanup; // Malicious filename detected
    }

    // 2. Construct the full file path
    size_t dir_path_len = strlen(dir_path);
    size_t filename_len = strlen(filename);
    // Determine if a '/' is needed between dir_path and filename
    int needs_slash = (dir_path_len > 0 && dir_path[dir_path_len - 1] != '/');

    // Calculate required length: length of dir_path + (1 for '/' if needed) + length of filename + 1 for null terminator
    // Check for potential overflow in path_len calculation before addition
    // (dir_path_len + needs_slash + filename_len + 1)
    if (dir_path_len > SIZE_MAX - (needs_slash + filename_len + 1)) {
        goto error_cleanup; // Path length calculation would overflow size_t
    }
    path_len = dir_path_len + needs_slash + filename_len + 1;

    full_path = (char *)malloc(path_len);
    if (full_path == NULL) {
        goto error_cleanup; // Memory allocation failed for path
    }

    // Use snprintf to safely concatenate the directory path and filename
    int snprintf_res;
    if (needs_slash) {
        snprintf_res = snprintf(full_path, path_len, "%s/%s", dir_path, filename);
    } else {
        snprintf_res = snprintf(full_path, path_len, "%s%s", dir_path, filename);
    }

    // Check for snprintf errors or truncation
    if (snprintf_res < 0 || (size_t)snprintf_res >= path_len) {
        goto error_cleanup; // Error in path construction or buffer too small
    }

    // 3. Open the file in binary read mode ("rb")
    file = fopen(full_path, "rb");
    if (file == NULL) {
        goto error_cleanup; // File not found, permission error, etc.
    }

    // 4. Determine file size
    if (fseek(file, 0, SEEK_END) != 0) {
        goto error_cleanup; // Error seeking to end of file
    }
    file_size_long = ftell(file);
    if (file_size_long == -1) { // ftell returns -1 on error
        goto error_cleanup; // Error getting file position
    }

    // --- SAFETY CRITIC: Integer Overflow Check for file_size ---
    // Ensure file_size_long is non-negative and fits into size_t,
    // and that file_size + 1 (for null terminator) doesn't overflow size_t.
    if (file_size_long < 0 || (unsigned long)file_size_long > SIZE_MAX - 1) {
        goto error_cleanup; // File too large to fit in memory or ftell error
    }
    file_size = (size_t)file_size_long; // Safe cast after checks

    if (fseek(file, 0, SEEK_SET) != 0) {
        goto error_cleanup; // Error seeking back to beginning of file
    }

    // 5. Allocate memory for the file content
    buffer = (char *)malloc(file_size + 1); // Add 1 for the null terminator
    if (buffer == NULL) {
        goto error_cleanup; // Memory allocation failed for content buffer
    }

    // 6. Read the entire file content into the buffer
    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        // Error reading or incomplete read (e.g., I/O error, file truncated during read)
        goto error_cleanup;
    }

    // 7. Null-terminate the string
    buffer[file_size] = '\0';

    // If all operations were successful, set the buffer as the result
    result = buffer;
    buffer = NULL; // Prevent 'buffer' from being freed in the cleanup block

cleanup:
    // Close the file if it was opened
    if (file != NULL) {
        fclose(file);
    }
    // Free the dynamically allocated full_path string
    if (full_path != NULL) {
        free(full_path);
    }
    // Free the content buffer if it was allocated but not returned (i.e., an error occurred)
    if (buffer != NULL) {
        free(buffer);
    }

    // If an error occurred (result is still NULL), allocate and return an empty string
    if (result == NULL) {
        result = (char *)malloc(1);
        if (result != NULL) {
            result[0] = '\0'; // Ensure it's an empty string
        }
        // If malloc(1) fails, result will remain NULL. This is a critical
