    encryption_result result = {NULL, 0, NULL, NULL};

    // --- Algorithm specific constants (AES-256-CBC chosen) ---
    // AES-256-CBC is a strong, widely used algorithm.
    const EVP_CIPHER *cipher_type = EVP_aes_256_cbc();
    const int KEY_BYTES = EVP_CIPHER_key_length(cipher_type); // 32 bytes for AES-256
    const int IV_BYTES = EVP_CIPHER_iv_length(cipher_type);   // 16 bytes for AES-CBC (also block size)

    // --- Input validation ---
    // The docstring guarantees key_len >= 64, but a defensive check is good practice.
    if (key == NULL || key_len < (size_t)KEY_BYTES) {
        // Input key is too short or NULL for the chosen algorithm.
        return result;
    }
    if (data == NULL || data_len == 0) {
        // No data to encrypt or invalid data pointer.
        // For an empty data_len, we return an empty result to indicate no meaningful encryption.
        return result;
    }

    // --- Allocate memory for result components ---
    // Allocate memory for the actual key used (prefix of the provided key)
    result.key = (unsigned char*)malloc(KEY_BYTES);
    if (result.key == NULL) {
        return result; // Malloc failed
    }
    memcpy(result.key, key, KEY_BYTES); // Use the prefix of the provided key

    // Allocate memory for the Initialization Vector (IV)
    result.iv = (unsigned char*)malloc(IV_BYTES);
    if (result.iv == NULL) {
        free(result.key); // Clean up previously allocated key
        result.key = NULL;
        return result; // Malloc failed
    }
    // Generate a cryptographically secure random IV
    if (RAND_bytes(result.iv, IV_BYTES) != 1) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Failed to generate random IV
    }

