    if (ctx == NULL) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        free(ciphertext); // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Failed to create EVP_CIPHER_CTX
