        final_padded_len = AES_BLOCK_SIZE;
        padding_value = AES_BLOCK_SIZE;
    } else {
        padding_value = AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE);
        if (padding_value == 0) { // data_len is already a multiple of block size
            padding_value = AES_BLOCK_SIZE; // Add a full block of padding
        }
        final_padded_len = data_len + padding_value;
    }

    // 2. Allocate and prepare input buffer with PKCS7 padding
    unsigned char* input_buffer_with_padding = (unsigned char*)malloc(final_padded_len);
    if (input_buffer_with_padding == NULL) {
        return result; // Return empty result on allocation failure
    }
    if (data_len > 0) {
        memcpy(input_buffer_with_padding, data, data_len);
    }
    memset(input_buffer_with_padding + data_len, padding_value, padding_value);

    // 3. Allocate memory for the encrypted data output
    unsigned char* encrypted_buffer = (unsigned char*)malloc(final_padded_len);
    if (encrypted_buffer == NULL) {
        free(input_buffer_with_padding); // Clean up previous allocation
        return result;
    }

    // 4. Generate a random Initialization Vector (IV)
    unsigned char iv_buffer[AES_BLOCK_SIZE];
    if (RAND_bytes(iv_buffer, AES_BLOCK_SIZE) != 1) {
        free(input_buffer_with_padding);
        free(encrypted_buffer);
        return result;
