    AES_KEY aes_key_struct;
    // AES_set_encrypt_key expects key length in bits.
    // Use the prefix of the provided key bytes (first AES_KEY_LENGTH_BYTES).
    if (AES_set_encrypt_key(key, AES_KEY_LENGTH_BITS, &aes_key_struct) < 0) {
        // This error typically indicates an invalid key length provided to AES_set_encrypt_key.
        // Given AES_KEY_LENGTH_BITS is 256, this should not occur unless OpenSSL is misconfigured.
