    // AES_cbc_encrypt modifies the IV buffer passed to it, so we use a copy
    // to preserve the original random IV for returning.
    unsigned char iv_for_encrypt_op[AES_BLOCK_SIZE];
    memcpy(iv_for_encrypt_op, iv_buffer, AES_BLOCK_SIZE);

    AES_cbc_encrypt(input_buffer_with_padding, encrypted_buffer, final_padded_len, &aes_key_struct, iv_for_encrypt_op, AES_ENCRYPT);

    // The temporary input buffer with padding is no longer needed
    free(input_buffer_with_padding);

    // 7. Populate the result structure with allocated copies of data
    result.encrypted_data = encrypted_buffer;
    result.encrypted_len = final_padded_len;

    result.iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    if (result.iv == NULL) {
        free(result.encrypted_data);
        result.encrypted_data = NULL;
        result.encrypted_len = 0;
        return result;
    }
    memcpy(result.iv, iv_buffer, AES_BLOCK_SIZE); // Copy the original IV

    result.key = (unsigned char*)malloc(AES_KEY_LENGTH_BYTES);
    if (result.key == NULL) {
        free(result.encrypted_data);
        free(result.iv);
