    // Convert the file descriptor to a FILE* stream for easier writing with fputs.
    // "w" mode truncates the file to zero length or creates it for writing.
    // Since mkstemp already created it, "w" is appropriate.
    FILE* temp_file = fdopen(fd, "w");
