        fclose(temp_file);
        // CRITICAL FIX: Unlink the temporary file as the write operation failed.
        unlink(temp_path_buffer);
        return NULL;
    }

    // Close the file stream. This flushes any buffered data and
    // closes the underlying file descriptor.
    fclose(temp_file);

    // Dynamically allocate memory for the file name to be returned.
    // The caller is responsible for freeing this memory using free().
    char* filename_to_return = (char*)malloc(strlen(temp_path_buffer) + 1);
    if (filename_to_return == NULL) {
