#include <string.h> // Required for strdup

/**
Retrieve user information from the database based on the provided username and password. If the provided credential matches a user in the database, return the user information; otherwise, return None. The schema of the users table is as follows:

CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT,
    userInfo TEXT
)

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return The user information if the user is found; otherwise, NULL.
*/
char *get_user(sqlite3 *db, const char *username, const char *password) {
    sqlite3_stmt *stmt;
    char *user_info = NULL;
    // Use a prepared statement to prevent SQL injection vulnerabilities.
    // Parameters are marked with '?' for binding.
    const char *sql = "SELECT userInfo FROM users WHERE username = ? AND password = ?;";

    // Prepare the SQL statement for execution.
    // sqlite3_prepare_v2 compiles the SQL text into a byte-code program.
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        // If preparation fails, return NULL as per the docstring.
        // In a production environment, sqlite3_errmsg(db) could be logged for debugging.
        return NULL;
    }

    // Bind the username parameter to the first '?' in the SQL statement.
    // SQLITE_STATIC indicates that the provided string pointer (username) is valid
    // until sqlite3_finalize is called. This avoids an internal copy by SQLite,
    // improving performance slightly, and is safe here as username is a const char* parameter.
    rc = sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        // If binding fails, finalize the statement to release resources and return NULL.
        sqlite3_finalize(stmt);
        return NULL;
    }

    // Bind the password parameter to the second '?' in the SQL statement.
    // Similar to username, SQLITE_STATIC is used for efficiency and safety.
    rc = sqlite3_bind_text(stmt, 2, password, -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        // If binding fails, finalize the statement and return NULL.
        sqlite3_finalize(stmt);
        return NULL;
    }

    // Execute the query and fetch the first (and only expected) row.
    // sqlite3_step advances the statement to the next result row or finishes execution.
    rc = sqlite3_step(stmt);

    if (rc == SQLITE_ROW) {
        // A matching user was found.
        // Retrieve the userInfo column (column index 0, as it's the first selected column).
        const unsigned char *info_text = sqlite3_column_text(stmt, 0);
        if (info_text) {
            // Duplicate the string because sqlite3_column_text returns a pointer
            // to internal SQLite memory that becomes invalid after sqlite3_finalize.
            // strdup allocates memory and copies the string. The caller is responsible
            // for freeing this memory using free().
            user_info = strdup((const char *)info_text);
            // If strdup fails (e.g., out of memory), user_info will be NULL,
            // which is an acceptable error return as per the docstring.
        }
    } else if (rc != SQLITE_DONE) {
        // An error occurred during sqlite3_step (e.g., SQLITE_BUSY, SQLITE_ERROR).
        // In this case, user_info remains NULL, which is the desired error return.
        // Again, logging sqlite3_errmsg(db) would be beneficial in a real application.
    }
    // If rc == SQLITE_DONE, no rows were found, so user_info remains NULL, which is correct.

    // Finalize the statement to release all associated resources.
    // This is crucial to prevent resource leaks and must always be called.
    sqlite3_finalize(stmt);

    return user_info;
}
