std::vector<std::pair<std::vector<unsigned char>, std::vector<unsigned char>>> hash_passwords(int count, const std::vector<std::string>& usernames, const std::vector<std::string>& passwords) {
    std::vector<std::pair<std::vector<unsigned char>, std::vector<unsigned char>>> results;

    // Handle the edge case where no passwords are to be hashed.
    if (count <= 0) {
        return results;
    }

    // Determine the length of the output hash (derived key) for SHA-256.
    // SHA-256 produces a 32-byte hash.
    const int key_len = EVP_MD_size(EVP_sha256());
    if (key_len <= 0) {
        // This indicates a serious OpenSSL configuration error or an invalid digest.
        // EVP_sha256() is a standard digest and should always return a positive size.
        throw std::runtime_error("Failed to get SHA-256 digest size from OpenSSL.");
    }
    // As specified, the salt length must be the same as the output hash length.
    const int salt_len = key_len;

    // Iterate through each password to hash it.
    for (int i = 0; i < count; ++i) {
        // Ensure that the 'passwords' vector has enough elements for the specified 'count'.
        // This prevents out-of-bounds access if 'count' is greater than the actual vector size.
        if (i >= passwords.size()) {
            throw std::out_of_range("The 'passwords' list is shorter than the specified 'count'.");
        }

        // 1. Generate a cryptographically secure random salt for the current password.
        std::vector<unsigned char> salt(salt_len);
        // RAND_bytes returns 1 on success, 0 on failure.
        if (RAND_bytes(salt.data(), salt_len) != 1) {
            // Failure to generate random bytes is a critical security issue.
            throw std::runtime_error("Failed to generate cryptographically secure random salt using RAND_bytes.");
        }

        // 2. Prepare an output buffer for the derived key (hashed password).
        std::vector<unsigned char> hashed_password(key_len);

        // 3. Call PKCS5_PBKDF2_HMAC to derive the key (hash the password).
        // Parameters:
        //   pass: const char *password         - The input password string.
        //   passlen: int password_len          - The length of the input password.
        //   salt: const unsigned char *salt    - The random salt.
        //   saltlen: int salt_len              - The length of the salt.
        //   iter: int iterations               - The number of iterations (10000 as specified).
        //   digest: const EVP_MD *digest       - The hash algorithm (EVP_sha256() as specified).
        //   keylen: int key_len                - The desired length of the derived key/hashed password.
        //   out: unsigned char *out            - The buffer to store the derived key.
        if (PKCS5_PBKDF2_HMAC(
                passwords[i].c_str(),
                static_cast<int>(passwords[i].length()), // Cast size_t to int for OpenSSL API compatibility
                salt.data(),
                salt_len,
                10000, // Specified number of iterations
                EVP_sha256(), // Specified digest algorithm (SHA-256)
                key_len,
                hashed_password.data()
            ) != 1) {
            // PKCS5_PBKDF2_HMAC returns 1 on success, 0 on failure.
            throw std::runtime_error("Failed to hash password using PKCS5_PBKDF2_HMAC.");
        }

        // 4. Store the generated hashed password and its corresponding salt as a pair.
        results.push_back({hashed_password, salt});
    }

    return results;
