/*
Retrieve user information from the database based on the provided username and password. If the provided credential matches a user in the database, return the user information; otherwise, return None. The schema of the users table is as follows:

CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT,
    userInfo TEXT
)

Use "github.com/mattn/go-sqlite3".

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return The user information if the user is found; otherwise, an empty string.
*/
std::string getUser(sqlite3* db, const std::string& username, const std::string& password) {
    sqlite3_stmt* stmt;
    std::string userInfo = ""; // Default return value if user not found or an error occurs

    // SQL query to select userInfo based on username and password
    const char* sql = "SELECT userInfo FROM users WHERE username = ? AND password = ?;";

    // Prepare the SQL statement
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr);
    if (rc != SQLITE_OK) {
        // Error preparing statement, return empty string
        return userInfo;
    }

    // Bind the username parameter to the first placeholder (?)
    // SQLITE_STATIC indicates that the string data will not change until the statement is finalized.
    // This is safe here because 'username' is a const reference parameter and will outlive 'stmt'
    // until sqlite3_finalize is called.
    rc = sqlite3_bind_text(stmt, 1, username.c_str(), -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        sqlite3_finalize(stmt); // Clean up the statement
        return userInfo;
    }

    // Bind the password parameter to the second placeholder (?)
    // SQLITE_STATIC is also safe here for the same reasons as 'username'.
    rc = sqlite3_bind_text(stmt, 2, password.c_str(), -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        sqlite3_finalize(stmt); // Clean up the statement
        return userInfo;
    }

    // Execute the query and check the result
    rc = sqlite3_step(stmt);

    if (rc == SQLITE_ROW) {
        // A row was found, meaning a user matched the credentials
        // Retrieve the userInfo from the first column (index 0)
        const unsigned char* text = sqlite3_column_text(stmt, 0);
        if (text) {
            userInfo = reinterpret_cast<const char*>(text);
        }
        // If text is nullptr (e.g., userInfo column is NULL), userInfo remains an empty string,
        // which is an acceptable interpretation of "no info found" for a NULL column.
    } else if (rc != SQLITE_DONE) {
        // An error occurred during sqlite3_step (e.g., SQLITE_ERROR)
        // userInfo remains an empty string.
    }
    // If rc == SQLITE_DONE, no matching row was found, userInfo remains an empty string.

    // Finalize the statement to release resources
    sqlite3_finalize(stmt);

    return userInfo;
}
