/**
Check if the provided email address is valid. For example, abc.123@def.ghi.com.uk is a valid email address. Cover as many cases as possible to avoid false negatives.

@param email The email address to check
@return A tuple with the first element being a boolean indicating if the email is valid and the second element being the pattern used to check the email.
*/
std::tuple<bool, std::string> check_email(const std::string& email) {
    // This regex is a comprehensive pattern designed to validate email addresses
    // according to a practical interpretation of RFCs (e.g., RFC 5322, RFC 5321),
    // aiming to cover a broad range of valid formats while minimizing false negatives.
    // It handles both unquoted and quoted local parts, and both hostname and IP address literal domains.

    // Breakdown of the regex:
    // ^                                  - Start of the string.

    // Local Part (before @):
    // (?:                                - Non-capturing group for the local part alternatives.
    //   [a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+  - Unquoted local part: first segment.
    //                                    - Allows alphanumeric, and a wide range of special characters.
    //   (?:\\.[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+)* - Subsequent dot-separated segments for unquoted local part.
    //                                    - Ensures dots are not consecutive, leading, or trailing in unquoted parts.
    // |                                  - OR
    //   \"(?:                             - Quoted local part: starts with a double quote.
    //     [\\x01-\\x08\\x0b\\x0c\\x0e-\\x1f\\x21\\x23-\\x5b\\x5d-\\x7f] - Allowed characters inside quotes (excluding control chars, backslash, and double quote).
    //     |                               - OR
    //     \\\\[\\x01-\\x09\\x0b\\x0c\\x0e-\\x7f] - Escaped characters (backslash followed by any allowed char).
    //   )*\"                               - Ends with a double quote.
    // )                                  - End of local part group.

    // @                                  - The literal at-sign separator.

    // Domain Part (after @):
    // (?:                                - Non-capturing group for the domain part alternatives.
    //   (?:                               - Hostname domain part.
    //     [a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\\. - Domain labels (e.g., "def.", "ghi.").
    //                                    - Each label starts and ends with an alphanumeric character,
    //                                    - and can contain hyphens in between.
    //                                    - Followed by a literal dot.
    //   )+                               - Ensures at least one 'label.' segment.
    //   [a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])? - The last label (Top-Level Domain - TLD).
    //                                    - Follows the same rules as other labels (no leading/trailing hyphens).
    // |                                  - OR
    //   \\[(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\] - IP Address Literal domain.
    //                                    - Matches IPv4 addresses enclosed in square brackets (e.g., [192.168.1.1]).
    // )                                  - End of domain part group.

    // $                                  - End of the string.

    const std::string email_pattern =
        "^(?:"
            "[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+"
            "(?:\\.[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+)*"
        "|"
            "\"(?:[\\x01-\\x08\\x0b\\x0c\\x0e-\\x1f\\x21\\x23-\\x5b\\x5d-\\x7f]|\\\\[\\x01-\\x09\\x0b\\x0c\\x0e-\\x7f])*\""
        ")"
        "@"
        "(?:"
            "(?:"
                "[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\\."
            ")+"
            "[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?"
        "|"
            "\\[(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\]"
        ")$";

    // Using std::regex_constants::ECMAScript for standard regex syntax.
    // This flag is important for character classes like \xNN and general regex behavior.
    std::regex regex_email(email_pattern, std::regex_constants::ECMAScript);

    bool is_valid = std::regex_match(email, regex_email);

    return std::make_tuple(is_valid, email_pattern);
}
