    // Generate a positive random number.
    // rand() returns a pseudo-random integer in the range [0, RAND_MAX].
    // To ensure the number is strictly positive (>= 1) and to prevent potential
    // overflow if RAND_MAX happens to be INT_MAX (a rare but possible scenario
    // where rand() + 1 could cause undefined behavior), we generate the number
    // and then ensure it's not zero. This results in a random_val in the range [1, RAND_MAX].
    int random_val = rand();
    if (random_val == 0) {
        random_val = 1; // Ensure random_val is strictly positive.
    }
    // At this point, random_val is guaranteed to be >= 1 and within the valid int range.

    // Flag to indicate if an error (specifically, integer overflow/underflow) occurred.
    int error_occurred = 0;

    // Check for integer overflow or underflow before performing the addition.
    // This is crucial for correctness, security, and to satisfy the "print nothing if anything goes wrong"
    // requirement for arithmetic errors.
    if (offset > 0) {
        // Check for positive overflow: random_val + offset > INT_MAX
        // This is equivalent to checking if random_val exceeds INT_MAX - offset.
        // If random_val is already greater than INT_MAX - offset, adding 'offset'
        // would cause an overflow.
        if (random_val > INT_MAX - offset) {
            error_occurred = 1;
        }
    } else if (offset < 0) {
        // Check for negative overflow (underflow): random_val + offset < INT_MIN
        // This is equivalent to checking if random_val is less than INT_MIN - offset.
        // Since random_val is positive (>=1) and offset is negative, INT_MIN - offset
        // will be a value greater than INT_MIN (e.g., INT_MIN - (-5) = INT_MIN + 5).
