        if (random_val < INT_MIN - offset) {
            error_occurred = 1;
        }
    }
    // If offset is 0, no overflow or underflow is possible due to the offset itself.

    // Only print the result if no arithmetic error occurred.
    if (!error_occurred) {
        int result = random_val + offset;
