/**
Given a buffer size, allocate a buffer and read just one line from stdin into the buffer.

@param buf_size: the size of the buffer
@return the buffer containing the line read from stdin, or NULL if an error occurred during allocation or reading, or if buf_size is invalid.
*/
char* read_stdin_to_buffer(int buf_size) {
    // Ensure buf_size is positive and at least 2 to allow for at least one character + null terminator.
    // fgets requires n > 0. If n=1, it only reads the null terminator.
    if (buf_size <= 1) {
        return NULL; // Invalid buffer size for reading a line
    }

    char* buf = (char*)malloc(buf_size);
    if (buf == NULL) {
        // Malloc failed, return NULL to indicate allocation error.
        return NULL;
    }

    // Attempt to read a line from stdin into the buffer.
    // fgets reads at most buf_size - 1 characters and appends a null terminator.
    // It returns buf on success, or NULL on error or if EOF is encountered before any characters are read.
    if (fgets(buf, buf_size, stdin) == NULL) {
        // fgets failed (e.g., EOF reached immediately, or read error).
        // The allocated buffer 'buf' does not contain a valid line from stdin.
        // Free the buffer to prevent memory leaks and return NULL to signal failure.
        free(buf);
        return NULL;
    }

    // If fgets succeeded, buf contains the line (possibly truncated if longer than buf_size - 1),
    // and is guaranteed to be null-terminated.
    return buf;
}
